#!/usr/bin/env python3
"""
patch-156 — Deliveries feature toggle.

Tenants opt in to the deliveries feature via Settings → Business.
Default OFF. When disabled:
  - Deliveries pill hidden from the Schedule sub-toggle
  - /admin/deliveries* routes 404 (all 4 controller methods guarded)
  - /admin/deliveries/resources* routes 404 (all 4 methods guarded)
  - deliveries:remind cron skips the tenant
  - "Delivery scheduled" and "Delivery reminder" rows in Notifications
    panel render as grayed-out, with a hint badge "Enable Deliveries to
    use" — keeps the feature discoverable for tenants who don't know
    it exists.

Mirrors the classes_enabled pattern (patch 88, April 2026).

Standalone Python. Idempotent.
"""
